:On Error exit
SET NOCOUNT ON;
IF OBJECT_ID(N'toolbelt_core.WorkItem',N'U') IS NULL THROW 54953,N'Lifecycle entfernte geschützte Tabelle WorkItem.',1;
IF EXISTS(SELECT [WorkItemId],[WorkTypeId],[PayloadJson],[Status],[EnqueuedAtUtc],[EnqueuedBy],[ClaimedAtUtc],[ClaimedBy],[ClaimToken],[ClaimGeneration],[LeaseDurationSeconds],[LeaseUntilUtc],[LastHeartbeatAtUtc],[RecoveryCount],[LastRecoveredAtUtc],[LastRecoveredBy],[CompletedAtUtc],[CompletedBy],[FailedAtUtc],[FailedBy],[FailureCode],[FailureMessage],[RowVersion],[ExecutionGroup],[Priority],[ExecutionMode],[IdempotencyKey],[MaxAttempts],[RetryBaseDelaySeconds],[RetryMaxDelaySeconds],[RetryCycleNumber],[CycleAttemptCount],[NextAttemptAtUtc],[LastErrorCode],[LastErrorMessage],[LastRetryScheduledAtUtc],[LastRetryScheduledBy],[DeadLetteredAtUtc],[DeadLetteredBy],[LastRequeuedAtUtc],[LastRequeuedBy],[LastRequeueReason],[BarrierEpoch],[ManagedReservationId],[ManagedHold],[ManagedCompletionNonce] FROM toolbelt_core.WorkItem EXCEPT SELECT [WorkItemId],[WorkTypeId],[PayloadJson],[Status],[EnqueuedAtUtc],[EnqueuedBy],[ClaimedAtUtc],[ClaimedBy],[ClaimToken],[ClaimGeneration],[LeaseDurationSeconds],[LeaseUntilUtc],[LastHeartbeatAtUtc],[RecoveryCount],[LastRecoveredAtUtc],[LastRecoveredBy],[CompletedAtUtc],[CompletedBy],[FailedAtUtc],[FailedBy],[FailureCode],[FailureMessage],[RowVersion],[ExecutionGroup],[Priority],[ExecutionMode],[IdempotencyKey],[MaxAttempts],[RetryBaseDelaySeconds],[RetryMaxDelaySeconds],[RetryCycleNumber],[CycleAttemptCount],[NextAttemptAtUtc],[LastErrorCode],[LastErrorMessage],[LastRetryScheduledAtUtc],[LastRetryScheduledBy],[DeadLetteredAtUtc],[DeadLetteredBy],[LastRequeuedAtUtc],[LastRequeuedBy],[LastRequeueReason],[BarrierEpoch],[ManagedReservationId],[ManagedHold],[ManagedCompletionNonce] FROM #LifeBeforeWorkItem) OR EXISTS(SELECT [WorkItemId],[WorkTypeId],[PayloadJson],[Status],[EnqueuedAtUtc],[EnqueuedBy],[ClaimedAtUtc],[ClaimedBy],[ClaimToken],[ClaimGeneration],[LeaseDurationSeconds],[LeaseUntilUtc],[LastHeartbeatAtUtc],[RecoveryCount],[LastRecoveredAtUtc],[LastRecoveredBy],[CompletedAtUtc],[CompletedBy],[FailedAtUtc],[FailedBy],[FailureCode],[FailureMessage],[RowVersion],[ExecutionGroup],[Priority],[ExecutionMode],[IdempotencyKey],[MaxAttempts],[RetryBaseDelaySeconds],[RetryMaxDelaySeconds],[RetryCycleNumber],[CycleAttemptCount],[NextAttemptAtUtc],[LastErrorCode],[LastErrorMessage],[LastRetryScheduledAtUtc],[LastRetryScheduledBy],[DeadLetteredAtUtc],[DeadLetteredBy],[LastRequeuedAtUtc],[LastRequeuedBy],[LastRequeueReason],[BarrierEpoch],[ManagedReservationId],[ManagedHold],[ManagedCompletionNonce] FROM #LifeBeforeWorkItem EXCEPT SELECT [WorkItemId],[WorkTypeId],[PayloadJson],[Status],[EnqueuedAtUtc],[EnqueuedBy],[ClaimedAtUtc],[ClaimedBy],[ClaimToken],[ClaimGeneration],[LeaseDurationSeconds],[LeaseUntilUtc],[LastHeartbeatAtUtc],[RecoveryCount],[LastRecoveredAtUtc],[LastRecoveredBy],[CompletedAtUtc],[CompletedBy],[FailedAtUtc],[FailedBy],[FailureCode],[FailureMessage],[RowVersion],[ExecutionGroup],[Priority],[ExecutionMode],[IdempotencyKey],[MaxAttempts],[RetryBaseDelaySeconds],[RetryMaxDelaySeconds],[RetryCycleNumber],[CycleAttemptCount],[NextAttemptAtUtc],[LastErrorCode],[LastErrorMessage],[LastRetryScheduledAtUtc],[LastRetryScheduledBy],[DeadLetteredAtUtc],[DeadLetteredBy],[LastRequeuedAtUtc],[LastRequeuedBy],[LastRequeueReason],[BarrierEpoch],[ManagedReservationId],[ManagedHold],[ManagedCompletionNonce] FROM toolbelt_core.WorkItem) THROW 54953,N'Abgewiesener Lifecycle änderte WorkItem.',2;
IF OBJECT_ID(N'toolbelt_core.WorkQueueManagedGate',N'U') IS NULL THROW 54953,N'Lifecycle entfernte geschützte Tabelle WorkQueueManagedGate.',1;
IF EXISTS(SELECT GateId,ManagedEnabled,AdmissionToken,PendingReservationId FROM toolbelt_core.WorkQueueManagedGate EXCEPT SELECT GateId,ManagedEnabled,AdmissionToken,PendingReservationId FROM #LifeBeforeWorkQueueManagedGate) OR EXISTS(SELECT GateId,ManagedEnabled,AdmissionToken,PendingReservationId FROM #LifeBeforeWorkQueueManagedGate EXCEPT SELECT GateId,ManagedEnabled,AdmissionToken,PendingReservationId FROM toolbelt_core.WorkQueueManagedGate) THROW 54953,N'Abgewiesener Lifecycle änderte WorkQueueManagedGate.',2;
IF OBJECT_ID(N'toolbelt_core.WorkerControlConfiguration',N'U') IS NULL THROW 54953,N'Lifecycle entfernte geschützte Tabelle WorkerControlConfiguration.',1;
IF EXISTS(SELECT ConfigurationId,MaxConcurrentExecutions,HeartbeatSeconds,UnreachableSeconds,CONVERT(binary(8),ConfigVersion) ConfigVersion FROM toolbelt_core.WorkerControlConfiguration EXCEPT SELECT ConfigurationId,MaxConcurrentExecutions,HeartbeatSeconds,UnreachableSeconds,ConfigVersion FROM #LifeBeforeWorkerControlConfiguration) OR EXISTS(SELECT ConfigurationId,MaxConcurrentExecutions,HeartbeatSeconds,UnreachableSeconds,ConfigVersion FROM #LifeBeforeWorkerControlConfiguration EXCEPT SELECT ConfigurationId,MaxConcurrentExecutions,HeartbeatSeconds,UnreachableSeconds,CONVERT(binary(8),ConfigVersion) ConfigVersion FROM toolbelt_core.WorkerControlConfiguration) THROW 54953,N'Abgewiesener Lifecycle änderte WorkerControlConfiguration.',2;
IF OBJECT_ID(N'toolbelt_core.WorkerRegistration',N'U') IS NULL THROW 54953,N'Lifecycle entfernte geschützte Tabelle WorkerRegistration.',1;
IF EXISTS(SELECT WorkerId,WorkerGeneration,WorkerToken,OwnerPrincipalId,ProviderKind,State,AdmissionPaused,Capacity,RunMode,LastHeartbeatAtUtc,HeartbeatSeconds,UnreachableSeconds FROM toolbelt_core.WorkerRegistration EXCEPT SELECT WorkerId,WorkerGeneration,WorkerToken,OwnerPrincipalId,ProviderKind,State,AdmissionPaused,Capacity,RunMode,LastHeartbeatAtUtc,HeartbeatSeconds,UnreachableSeconds FROM #LifeBeforeWorkerRegistration) OR EXISTS(SELECT WorkerId,WorkerGeneration,WorkerToken,OwnerPrincipalId,ProviderKind,State,AdmissionPaused,Capacity,RunMode,LastHeartbeatAtUtc,HeartbeatSeconds,UnreachableSeconds FROM #LifeBeforeWorkerRegistration EXCEPT SELECT WorkerId,WorkerGeneration,WorkerToken,OwnerPrincipalId,ProviderKind,State,AdmissionPaused,Capacity,RunMode,LastHeartbeatAtUtc,HeartbeatSeconds,UnreachableSeconds FROM toolbelt_core.WorkerRegistration) THROW 54953,N'Abgewiesener Lifecycle änderte WorkerRegistration.',2;
IF OBJECT_ID(N'toolbelt_core.WorkerSlotReservation',N'U') IS NULL THROW 54953,N'Lifecycle entfernte geschützte Tabelle WorkerSlotReservation.',1;
IF EXISTS(SELECT SlotReservationId,WorkerId,WorkerGeneration,WorkItemId,ClaimGeneration,ClaimToken,ExecutionId,State,IsOccupied,AttemptNonce,BoundPrincipalId,CreatedAtUtc,EndedAtUtc FROM toolbelt_core.WorkerSlotReservation EXCEPT SELECT SlotReservationId,WorkerId,WorkerGeneration,WorkItemId,ClaimGeneration,ClaimToken,ExecutionId,State,IsOccupied,AttemptNonce,BoundPrincipalId,CreatedAtUtc,EndedAtUtc FROM #LifeBeforeWorkerSlotReservation) OR EXISTS(SELECT SlotReservationId,WorkerId,WorkerGeneration,WorkItemId,ClaimGeneration,ClaimToken,ExecutionId,State,IsOccupied,AttemptNonce,BoundPrincipalId,CreatedAtUtc,EndedAtUtc FROM #LifeBeforeWorkerSlotReservation EXCEPT SELECT SlotReservationId,WorkerId,WorkerGeneration,WorkItemId,ClaimGeneration,ClaimToken,ExecutionId,State,IsOccupied,AttemptNonce,BoundPrincipalId,CreatedAtUtc,EndedAtUtc FROM toolbelt_core.WorkerSlotReservation) THROW 54953,N'Abgewiesener Lifecycle änderte WorkerSlotReservation.',2;
IF OBJECT_ID(N'toolbelt_core.WorkerExecutionDisposition',N'U') IS NULL THROW 54953,N'Lifecycle entfernte geschützte Tabelle WorkerExecutionDisposition.',1;
IF EXISTS(SELECT WorkItemId,SlotReservationId,IsHeld,StopStatus,CONVERT(binary(8),HoldVersion) HoldVersion FROM toolbelt_core.WorkerExecutionDisposition EXCEPT SELECT WorkItemId,SlotReservationId,IsHeld,StopStatus,HoldVersion FROM #LifeBeforeWorkerExecutionDisposition) OR EXISTS(SELECT WorkItemId,SlotReservationId,IsHeld,StopStatus,HoldVersion FROM #LifeBeforeWorkerExecutionDisposition EXCEPT SELECT WorkItemId,SlotReservationId,IsHeld,StopStatus,CONVERT(binary(8),HoldVersion) HoldVersion FROM toolbelt_core.WorkerExecutionDisposition) THROW 54953,N'Abgewiesener Lifecycle änderte WorkerExecutionDisposition.',2;
IF OBJECT_ID(N'toolbelt_core.WorkerExecutionCommitWitness',N'U') IS NULL THROW 54953,N'Lifecycle entfernte geschützte Tabelle WorkerExecutionCommitWitness.',1;
IF EXISTS(SELECT SlotReservationId,AttemptNonce,ExecutionId,ClaimGeneration,RecordedAtUtc FROM toolbelt_core.WorkerExecutionCommitWitness EXCEPT SELECT SlotReservationId,AttemptNonce,ExecutionId,ClaimGeneration,RecordedAtUtc FROM #LifeBeforeWorkerExecutionCommitWitness) OR EXISTS(SELECT SlotReservationId,AttemptNonce,ExecutionId,ClaimGeneration,RecordedAtUtc FROM #LifeBeforeWorkerExecutionCommitWitness EXCEPT SELECT SlotReservationId,AttemptNonce,ExecutionId,ClaimGeneration,RecordedAtUtc FROM toolbelt_core.WorkerExecutionCommitWitness) THROW 54953,N'Abgewiesener Lifecycle änderte WorkerExecutionCommitWitness.',2;
IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'Toolbelt.Module.toolbelt.core.worker-control.Version' AND CONVERT(nvarchar(64),value)=N'1.0.0') OR NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'Toolbelt.Module.toolbelt.core.work-queue.Version' AND CONVERT(nvarchar(64),value)=N'2.1.0') THROW 54953,N'Modulversion wurde verändert.',3;
SELECT CAST('PASS' AS varchar(16)) LifecycleSnapshotRowsPreserved;
